/**
 * Appends the common connection, plugin and source options to the
 * given arguments array based on the current command arguments.
 *
 * @param array $newArgs The arguments array to append to.
 * @param \Cake\Console\Arguments $args The command arguments.
 * @return void
 */
protected function appendCommonOptions(array &$newArgs, Arguments $args): void
{
    if ($args->getOption('connection')) {
        $newArgs[] = '-c';
        $newArgs[] = $args->getOption('connection');
    }

    if ($args->getOption('plugin')) {
        $newArgs[] = '-p';
        $newArgs[] = $args->getOption('plugin');
    }

    if ($args->getOption('source')) {
        $newArgs[] = '-s';
        $newArgs[] = $args->getOption('source');
    }
}

